	('9c496e9b-bef1-414b-9d99-fde984d89f4f', 'CREATED', 'CONTROL_DEFINITION', 'd5395b29-bc97-4431-86d6-838fe16ced87', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "ACCESS-02_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('9db53450-7f22-4ba6-b8d0-3e99c443a6b1', 'CREATED', 'CONTROL_DEFINITION_VERSION', '23bbb100-9d7b-416e-89ff-708a61f121f8', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_ACCESS", "objective": "Activities performed by IT members with privileged accesses must be reviewed :\n- For GxP regulated digital solution, the review of activities must be covered as applicable by the audit trail review\n- For SOX & CSRD regulated digital solution, activities of IT accounts with extended rights (e.g. Firefighters, Privileged accounts) which can have impacts on SOX/CSRD data must be reviewed and documented at least annually.", "ownerTeam": "CYBER_SECURITY", "statement": "Activities Review for privileged accesses", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "d5395b29-bc97-4431-86d6-838fe16ced87", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. GQCMS-QU-STD-0000452-User Access Management Controls: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/867621\n2. DFC-QU-STD-0000298-Access Control: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/581828\n3. DIG-CO-SOP-0015241-SAP Security Baseline: https://opella-connect.veevavault.com/ui/#permalink=V190000000JN001\n4. DFC-QU-SOP-0087024-Business Application Access Management: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/738198", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "* Audit trail review record/report for GxP-regulated digital solutions, covering activities performed under privileged access\n* Documented review log for SOX/CSRD-regulated solutions, covering extended-rights accounts (e.g. Firefighter, Privileged accounts), performed and evidenced at least annually* Reviewer sign-off/approval confirming the review was completed (name, date, scope covered)\n* Record of any anomalies or inappropriate activity identified during the review, with follow-up/remediation evidence\n* List of in-scope privileged/extended-rights accounts at the time of review, to confirm completeness of coverage", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n \n -Is a review of activities performed with IT privileged accesses conducted and documented for GxP, SOX and CSRD digital solutions?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('fee09426-17f5-4653-be9c-5226b0779d8a', 'CREATED', 'CONTROL_DEFINITION', 'e21e3964-9c53-4d6e-89f7-42d302b93adf', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "B&R-01_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('724e7c5b-a2ca-4e26-9b75-da84fa3f3648', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'b76399e8-d686-47a4-9496-6ed68aa2c741', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "DEPLOY", "itProcess": "MANAGE_CONTINUITY", "objective": "Digital solutions must have backup implemented (scheduled, executed and monitored) to meet business needs.", "ownerTeam": "CYBER_SECURITY", "statement": "Backup implementation", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}, {"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["LIKE_EXTERNAL"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}, {"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["FULLY_MANAGED"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}]}, "definitionId": "e21e3964-9c53-4d6e-89f7-42d302b93adf", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DFC-QU-SOP-0086073-Backup and Restore - Infrastructure: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/477883", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Backup requirements describing all the components to be backed up with the required SLA documented and implemented with effective monitoring in place.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\nBack-up set up:\n- Is backup specification documented for the digital solution using the backup specification template?\n- Is the backup configured?\n\nMonitoring and logs:\n- Is the backup monitoring effective and are failures captured?\n- Are the logs traceable and retained for ≥ 6 months?\n\n- For digital solution hosted externally, are back up requirements covered in the contractual clauses with the Third Party?", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('10ddb6e3-c338-4b76-ab67-67fa1ad3e1cb', 'CREATED', 'CONTROL_DEFINITION', '6a8759f5-1ab5-4d84-9108-84b4526d05b8', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "BC-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('2cac41f4-29ed-46ae-b7d1-fdcd344ed2ec', 'CREATED', 'CONTROL_DEFINITION_VERSION', '149f68bc-68cc-470c-85b5-8ff0b5325d60', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "A business continuity management process must be defined (e.g., Business Continuity Plan) at business process level with adequate measures established and tested (including Disaster Recovery strategy activation if applicable) to ensure business operations during digital solution’s unavailability (e.g., disasters). This process must be maintained and regularly reviewed to ensure its effectiveness and accuracy.", "ownerTeam": "CYBER_SECURITY", "statement": "Business Continuity", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "6a8759f5-1ab5-4d84-9108-84b4526d05b8", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009\n2. QUA-CO-OPE-0093984-Business Continuity Plan for GxP Computerized Systems: https://opella-connect.veevavault.com/ui/#permalink=V190000000EQ023", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Actionable business continuity plan describing how the business activities will be executed in case of digital solution''s unavailability.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n* Is a Business Continuity Plan (BCP) defined at the business process level for this digital solution?\n* Does the BCP describe adequate measure to sustain business activities during the solutions'' unavailability (e.g. manual workarounds, alternate processes)?\n* For applicable solutions: does the BCP include Disaster Recovery strategy activation steps?\n* Is the BCP reviewed and updated on a regular cadence to ensure it remains accurate and effective (e.g. after solution changes, org changes, or prior test findings)?\n* Is the BCP readily accessible to the people who would need to execute it during an actual disruption?\n* Any digital solution without a maintained, tested BCP - or with a BCP that hasn''t been reviewed within its required cycle - should be treated as non-complaint.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('42e1cff0-5ad6-407e-b455-433c393636f4', 'CREATED', 'CONTROL_DEFINITION', '340de438-5887-40f3-8e89-5b300036b4c0', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "BC-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('183fd88d-f35f-404e-84b7-faae8e095c66', 'CREATED', 'CONTROL_DEFINITION_VERSION', '25f9224d-11ca-49e6-aec7-b4ea44eab37f', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure business continuity can be maintained when the digital solution becomes unavailable.", "ownerTeam": "CYBER_SECURITY", "statement": "Alternate Procedures and Continuity Measures", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "340de438-5887-40f3-8e89-5b300036b4c0", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Documented alternate procedures\nBusiness Continuity Plan\nWork instructions\nTraining material\nExercise or test results\nEvidence of periodic review and update\nCorrective actions arising from continuity exercises", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\nDocumentation\nAre alternative procedures documented for the affected business activities?\nAre the procedures sufficiently detailed for users to execute them without relying on undocumented knowledge?\nAre roles and responsibilities clearly defined?\nAvailability\nAre the documented procedures available to the personnel who would need to execute them during a disruption?\nCan the procedures be accessed if the digital solution is unavailable?\nTraining\nHave relevant personnel been trained on the alternative procedures?\nIs training evidence available?\nTesting\nHave the alternative procedures been exercised, tested, or used in practice?\nWere the exercises documented?\nWere lessons learned captured?\nMaintenance\nHave the procedures been reviewed within the defined review cycle?\nHave changes in processes, systems, suppliers, or organization been reflected in the procedures?\nEffectiveness\nWould the alternative procedures allow the business activity to continue for the expected disruption period?\nAre there significant manual dependencies or bottlenecks that could prevent successful execution?\nWere any issues identified during testing remediated and tracked to closure?\n\nNon-Compliance Indicators\n\nThe control should be considered non-compliant when:\n\nNo alternative procedure exists.\nProcedures are undocumented.\nProcedures have never been tested.\nPersonnel are unaware of the procedures.\nProcedures are outdated or no longer applicable.\nSignificant deficiencies identified during testing remain unresolved.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('0a822ace-0464-4a8b-9d7e-e95604292e4d', 'CREATED', 'CONTROL_DEFINITION', '02e3700c-d275-47cc-b579-4dfade074445', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('ee35f006-cd31-4b08-977b-ddf102e9c9fe', 'CREATED', 'CONTROL_DEFINITION_VERSION', '4ad4d085-93dd-4a5e-98a2-1aed58e1417a', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Vital digital solutions shall demonstrate through testing and documented evidence that recovery can be completed within the approved Recovery Time Objective.", "ownerTeam": "CYBER_SECURITY", "statement": "Recovery Time Objective Demonstration", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "02e3700c-d275-47cc-b579-4dfade074445", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Recovery exercise\nRecovery exercise report\nRecovery timings documented: Start time, End time, Measured RTO\nData recovery validated\nDeviations documented and remediated", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\nRecovery Performance\nHas recovery been timed?\nWas recovery completed within the approved RTO (Platinum RTO ≤2; Gold RTO ≤ 4 hours)?\nWas the approved RPO achieved (≤ 15 mins)?\nWere all critical services, data and integrations restored?\nWere all critical services restored?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('691d55e3-5d3f-4663-b450-ddd9cd864d7a', 'CREATED', 'CONTROL_DEFINITION', '57b5ff92-d988-44a4-b235-9403fd874938', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('f6d41363-3d3d-4400-ad62-6eac384a24a4', 'CREATED', 'CONTROL_DEFINITION_VERSION', '5acd55d0-92cd-4b34-a5a0-4f6005d00624', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Dependencies required for recovery shall be identified, documented, and included in recovery procedures and testing activities.", "ownerTeam": "CYBER_SECURITY", "statement": "Critical Dependency Identification and Recovery Sequencing", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "57b5ff92-d988-44a4-b235-9403fd874938", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Dependency map\nRecovery sequence\nArchitecture documentation", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\nDependency Identification\nHave all business, technical, infrastructure, security, data, identity, network, integration, and third-party dependencies required for operation and recovery of the digital solution been identified?\nAre dependencies documented in architecture diagrams, recovery procedures, or dependency inventories?\nDoes the dependency inventory include both internal and external services?\nSingle Points of Failure\nHave potential single points of failure been identified and assessed?\nHave mitigation measures been implemented, documented, or formally accepted through risk management processes?\nRecovery Sequence\nIs the recovery sequence documented?\nDoes the recovery sequence identify which systems, services, databases, integrations, and infrastructure components must be recovered first?\nIs the recovery order consistent with the documented recovery procedures?\nRecovery Objectives\nAre dependency recovery objectives aligned with the digital solution''s Recovery Time Objective (RTO) and Recovery Point Objective (RPO)?\nCould any dependency prevent achievement of the approved recovery objectives?\nThird-Party Dependencies\nFor externally provided services, are supplier recovery responsibilities documented?\nHas the supplier demonstrated recovery capability through testing, assurance reports, or contractual commitments?\nEvidence Quality\nIs there evidence that dependency information has been reviewed and updated following significant architecture, supplier, or infrastructure changes?\nNon-Compliance Indicators\n\nThe control should be considered non-compliant if:\n\nCritical dependencies are unknown or undocumented.\nRecovery sequencing is not defined.\nDependency recovery objectives exceed the solution''s approved RTO or RPO.\nSingle points of failure have not been assessed.\nRecovery relies on undocumented supplier capabilities.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('0f52e3bb-ce3b-4850-92bd-40aa5860a87f', 'CREATED', 'CONTROL_DEFINITION', 'f559c7bb-a799-43f8-9405-e4f60f812a77', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-03", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('75106e87-bfa5-4692-8536-a1e70ae85573', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'd1d056af-90a2-4ba7-84d9-2b30bf05de88', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure recovery objectives and recovery capabilities are defined, implemented, tested, and aligned with the assigned Recovery Tier and Business Criticality classification of the digital solution.", "ownerTeam": "CYBER_SECURITY", "statement": "Vital Application Recovery Readiness Review", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "f559c7bb-a799-43f8-9405-e4f60f812a77", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Annual review report\nAction tracking\nUpdated DR documentation", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\nRecovery Asset Protection\nAre recovery assets identified and documented?\nDo recovery assets include backups, configurations, infrastructure definitions, application components, scripts, documentation, recovery credentials, and recovery environments where applicable?\nAre recovery assets protected from unauthorized modification or deletion?\nRecovery Environment\nIs a recovery environment available and documented?\nCan recovery activities be executed independently from a compromised production environment?\nAre recovery procedures clearly documented?\nRecovery Credentials\nAre recovery accounts and credentials protected and managed appropriately?\nCan recovery activities still be performed if production privileged accounts are unavailable or compromised?\nRecovery Integrity\nAre processes defined to verify the integrity and validity of recovered systems, data, and configurations?\nDoes the recovery process include validation activities before restored services are returned to operation?\nTesting and Validation\nHas the recovery design been tested?\nDo test results demonstrate successful recovery of the required components?\nWere recovery issues identified during testing tracked and remediated?\nRecovery Objective Achievement\nDoes available evidence demonstrate that the cyber recovery design can support the approved Recovery Time Objective (RTO) and Recovery Point Objective (RPO)?\nFor Vital applications, does the design demonstrate capability to support Platinum recovery requirements?\nThird-Party Recovery\nFor externally hosted or supplier-supported solutions, has evidence been reviewed demonstrating the supplier''s ability to support recovery requirements?\nAre responsibilities clearly documented through a Shared Responsibility Model?\n\nCompliance Indicators\nPass\nRecovery Tier assigned.\nRTO and RPO defined.\nRecovery capability documented.\nRecovery capability tested or validated.\nNo material open recovery gaps.\n\nConditional Pass\nRecovery capability exists.\nMinor documentation, testing, or remediation gaps remain.\nDefined action plan exists.\n\nFail\nRecovery Tier not assigned.\nRecovery objectives undefined.\nRecovery capability not documented.\nNo evidence of recovery validation.\nMaterial recovery gaps remain unmanaged.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('910696b4-2ea8-4ceb-af79-6303748950c6', 'CREATED', 'CONTROL_DEFINITION', '373ad753-7c55-463f-bb6c-f0b79d793243', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RES-04", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('f03286b4-c62a-466a-b067-4b110f595f99', 'CREATED', 'CONTROL_DEFINITION_VERSION', '17ccf545-f20e-4387-bd4b-f23c24cbb6d7', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_CONTINUITY", "objective": "Ensure the digital solution can demonstrably recover within approved recovery objectives and that recovery capabilities remain effective throughout the solution lifecycle.", "ownerTeam": "CYBER_SECURITY", "statement": "Recovery Objective Validation", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "373ad753-7c55-463f-bb6c-f0b79d793243", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-OPE-0293533-Corporate Digital Service Continuity and Disaster Recovery Standard\nSECU-CO-MAN-0000101-Business Continuity Management Policy", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Recovery test reports\nDisaster Recovery exercise reports\nMeasured recovery duration\nMeasured data recovery point\nRecovery validation evidence\nRecovery improvement actions\nTest result approvals\nSupplier recovery testing evidence (where applicable)", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\nRecovery Testing\nHas a recovery exercise been performed?\nWas the recovery exercise completed using documented recovery procedures?\nWas the exercise representative of the recovery scenario being evaluated?\nRecovery Time Objective (RTO)\nWas the actual recovery duration measured?\nDid the digital solution achieve the approved Recovery Time Objective?\nIf the approved RTO was not achieved, was a remediation plan documented?\nRecovery Point Objective (RPO)\nWas the actual data recovery point measured?\nDid the digital solution achieve the approved Recovery Point Objective?\nWas any data loss within the approved tolerance?\nRecovery Scope\nWere all critical solution components recovered?\nWere critical data, configurations, interfaces, integrations, and supporting services included in the recovery validation?\nWere dependencies recovered and operational?\nBusiness Validation\nWas business functionality validated following recovery?\nWere business users involved where appropriate?\nWas the recovered solution demonstrated to be fit for use?\nRemediation and Continuous Improvement\nWere recovery issues, delays, or failures documented?\nWere corrective actions assigned and tracked?\nHas evidence of remediation been reviewed when required?\nThird-Party Recovery\n\nFor supplier-supported solutions:\n\nHas supplier recovery evidence been reviewed?\nHas the supplier demonstrated recovery capability consistent with contractual commitments?\nAre supplier recovery responsibilities clearly documented?\nNon-Compliance Indicators\n\nThis control should be considered non-compliant if:\n\nRecovery exercises have not been performed.\nRecovery objectives cannot be demonstrated.\nRecovery time was not measured.\nRecovery point was not measured.\nRecovery exceeded approved objectives without remediation.\nCritical components were not included in testing.\nRecovery evidence is unavailable.\nSupplier recovery capabilities cannot be demonstrated where applicable.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('46aaee2e-fe9f-4343-9277-bb3d4fa70107', 'CREATED', 'CONTROL_DEFINITION', '411ab695-5b02-4bbb-91ce-74dd26e8dfd7', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DP-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('0d103a5a-8dd9-4ec0-9752-db6975538cbb', 'CREATED', 'CONTROL_DEFINITION_VERSION', '4ed8cbba-c893-4f38-9de2-4640559140c9', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "PLAN", "itProcess": "MANAGE_RISK", "objective": "The  the digital solution must undergo a privacy Data Asset Assessment (DAA) to evaluate compliance with privacy requirements.", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "Execute Personal Data Privacy Assessment", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "411ab695-5b02-4bbb-91ce-74dd26e8dfd7", "reviewerTeam": "DATA_PRIVACY", "sourceOfTruth": "1. EBI-CO-STD-0000410-Opella Data Privacy Standard (v1.0)\nhttps://opella-connect.veevavault.com/ui/#permalink=V190000000KB037\n\n2. Privacy Hub\nhttps://sanofi.sharepoint.com/sites/opella-compliance-site/SitePages/Work-with-personal-data-v1.0.aspx?CT=1736934649051&OR=OWA-NT-Mail&CID=47d9fdb6-098e-ddca-947b-ad4f41eab8f3", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Personal Data Privacy Assessment documented in OneTrust.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "1. The digital solution is inventoried as \"digital asset\" in the Opella Privacy Care (One Trust) asset inventory\n2. A Digital Asset Assessment exists and it is either in status \"Completed\" or \"Completed with open risks\"\n3. If the Digital Asset Assessment is \"completed with open risks\", all the risks must be in a status different from \"Ongoing mitigation\" (Avoided, Reduced, Accepted, Expired or Materialized)", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('e596c2c5-cec1-4ae8-a15b-78a83722153a', 'CREATED', 'CONTROL_DEFINITION', 'f1f6d392-d5cb-4224-9145-d832dc717bde', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DP-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('dfdec01a-2ce9-496e-8346-0bba453cf168', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'e91b71a8-3fbd-44c2-b8bb-8f96f143dcb7', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "PLAN", "itProcess": "MANAGE_RISK", "objective": "The owner of the digital solution must self attest compliance with a list of requirements, depending on the type of the digital solution", "ownerTeam": "DATA_PRIVACY_OFFICE", "statement": "Complete Privacy Compliance Declaratoin", "triggerRule": null, "definitionId": "f1f6d392-d5cb-4224-9145-d832dc717bde", "reviewerTeam": "DATA_PRIVACY", "sourceOfTruth": "1. EBI-CO-STD-0000410-Opella Data Privacy Standard (v1.0)\nhttps://opella-connect.veevavault.com/ui/#permalink=V190000000KB037\n\n2. Privacy Hub\nhttps://sanofi.sharepoint.com/sites/opella-compliance-site/SitePages/Work-with-personal-data-v1.0.aspx?CT=1736934649051&OR=OWA-NT-Mail&CID=47d9fdb6-098e-ddca-947b-ad4f41eab8f4", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": false, "targetedEvidence": "Privacy Compliance declaration in the risk profiling tool", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "The owner of the Digital Property must self-attest compliance with certain requirements depending on the digital property type, as a mandatory pre-condition for go-live approval\n\nFor all Digital Solutions, this will be captured in OneTrust when the Digital Assessment is performed.", "autoAttestationRule": null, "assessmentTemplateKey": "DATA_PRIVACY_SELF_ASSESSMENT_V1", "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('9be03927-313c-4fe1-af2f-a6467e66be2b', 'CREATED', 'CONTROL_DEFINITION', '5a644ddb-91a5-4cd4-944e-9912c2343ab5', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('6857736e-dbf1-42e0-8799-ad0b78b4c927', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'c24d385d-baa5-4a5f-b3ac-8d58d3481ae5', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have a defined set of requirements that describe the functional (i.e., business-process related) and non-functional (e.g., Audit Trail, Electronic Record, Electronic Signature, Data Privacy, Cybersecurity) needs to satisfy the business. All requirements must be specific, measurable, achievable, realistic and testable (SMART).", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Gather Requirements", "triggerRule": null, "definitionId": "5a644ddb-91a5-4cd4-944e-9912c2343ab5", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "The requirements the digital solution must meet, including the list of requirements supporting the business process, as well as the applicable non functional requirements.\nE.g.: Epic and user stories in Jira, Requirements in HP ALM, Requirement document in Connect CMS...", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n* Are both functional (business-process related) and non-functional requirements (e.g. Audit Trail, Electronic Record, Electronic Signature, Data Privacy, Cybersecurity) documented for the digital solution?\n* Is each requirement specific, measurable, achievable, realistic, and testable (SMART)?\n* Are requirements captured and traceable in the appropriate tool for the solution (e.g. Epics/user stories in JIRA, requirements in HP ALM, requirement document in Connect CMS)?\n* Is there evidence requirements were reviewed/approved by the appropriate business and IT stakeholders before design/build began?\n* Are requirements complete relative to the business process being supported, with no material gaps identified later in the lifecycle?\n* Any digital solution where requirements are missing, non-SMART, or not traceable to a recognized system of record should be treated as noncompliant", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('287d2017-34eb-479f-81fe-29142a23d87f', 'CREATED', 'CONTROL_DEFINITION', 'a0135f5b-8754-4921-8681-c7b75e2a1417', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-10", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('ba12a395-06ba-4850-a44f-363b4d0f0f73', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'cbb5e38b-2070-4562-b113-1cf7e798d63a', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have traceability by linking requirements to its specifications and testing artifacts.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Ensure Traceability", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "a0135f5b-8754-4921-8681-c7b75e2a1417", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Matrix demonstrating traceability between the requirements, specifications and tests.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following: \n\n* Is a traceability matrix in place linking each requirement to its corresponding specification(s)?\n* Does the matrix also link each requirement/specification to its corresponding test artifact (test case/script)?\n* Is coverage complete - i.e can every requirement be traced through to a specification and a test, with no orphaned requirements or untested specifications?\n* Is the traceability matrix kept current as requirements, specifications, or test artifacts change throughout the lifecycle?\n* Can the matrix be used to demonstrate full lifecycle coverage during an audit or inspection (particularly for GxP solutions)?\n* Any digital solution where requirements cannot be traced end-to-end to specifications and tests should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('31714572-2b12-4534-a01c-e3621326017b', 'CREATED', 'CONTROL_DEFINITION', 'e8f613b0-8cc9-47c5-98a5-0dc10f2df9f3', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-13_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('6a2e53ec-8290-4d68-9491-36befadadd9c', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'ab58a603-c8da-4ab2-959b-7bd7f9e69810', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "DEPLOY", "itProcess": "MANAGE_DELIVERY", "objective": "A summary of controls execution (as per the defined control strategy) must be documented to authorize the usage of the digital solution. Deviations from the controls strategy must be justified. For unresolved deviations, actions plans must be recorded to monitor their resolutions until closure.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Authorize for Use", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "e8f613b0-8cc9-47c5-98a5-0dc10f2df9f3", "reviewerTeam": "PRODUCT_PROJECT_DELIVERY", "sourceOfTruth": "DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Summary of the Control/Validation Strategy execution, including at least:\n - all the applicable controls and their achivement''s details\n - deviations from the strategy with associated justification and action plan to remediate them\n- the readiness status of the operational & maintenance processes\n- decision to authorize the usage of the digital solution\nE.g.: Authorization for use, Release report", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n- Has a summary of controls executed been documented?\n- Are all controls defined in the control strategy implemented? If not, are deviations justified?\n- For any unresolved deviations, is there an action plan defined with an assigned owner and due date?\n- Based on their impact, are there any unresolved deviation that would block the authorization for use?\n- Have operational readiness activities been properly executed to ensure the digital solution is ready for operation?\n- Has a comprehensive review of control execution, deviations, and operational readiness been conducted to make an informed decision on authorizing the usage of the digital solution?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('aac097fe-fe6f-4eab-92f3-ffacab0ce28e', 'CREATED', 'CONTROL_DEFINITION', '5f9d437d-d787-4a9e-9cb1-2b642e65b3f1', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-14", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('97caabfb-3ee1-4e78-b536-d1684b18198a', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'e6845b40-54cc-4eef-bb8d-0cd36c6a7d11', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution identified as digital property must adhere to the Digital Properties process.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Execute Digital Properties Process", "triggerRule": null, "definitionId": "5f9d437d-d787-4a9e-9cb1-2b642e65b3f1", "reviewerTeam": null, "sourceOfTruth": "DFC-QU-GOP-0000613-Life Cycle Management of Digital Properties: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/860315", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": false, "targetedEvidence": "Reference of the digital solution recorded in Digital Property Registry.", "applicabilityType": "ALWAYS", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Reference of the digital solution recorded in Digital Property Registry.", "autoAttestationRule": {"outcomeKey": "PROPERTY_TYPE", "acceptedValues": ["WEBSITE", "SOCIAL", "MOBILE_APP", "CHATBOT"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
