	('86553be7-0d1f-4455-9806-8307d1db90dd', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'ae8e006c-d644-4efb-920f-eedb9b986a87', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The AI solution risk assessment shall be documented and approved before deployment.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Risk Assessment", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "e598d4a3-b0d8-4251-a0ba-03155a184430", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Completed AI Risk Assessment, approval record", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Has an AI risk assessment been completed before deployment? Has the solution been classified according to the applicable AI risk categories? Have significant risks, limitations, and mitigation measures been documented? Has the AI risk assessment been reviewed and approved by the appropriate stakeholders?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
