	('f6b6fde5-1856-44b4-b98a-eb80ac9f659b', 'CREATED', 'CONTROL_DEFINITION_VERSION', '11138d07-2197-46e5-8c01-de4231b0c8fc', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The AI solution shall have documented intended purpose, architecture, limitations, risks and usage instructions.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Documentation", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "3f656d36-ecd7-4a54-84d6-caadb07de28a", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "AI Solution Documentation, Architecture Diagram", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Is the intended purpose of the AI solution documented? Are the architecture, AI models, data sources, knowledge sources, and integrations documented? Are the known limitations, assumptions, and risks documented? Are user instructions and operating procedures available? Is documentation maintained throughout the solution lifecycle?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
