	('d1bff150-f93c-44ed-ab7e-d937e0b32375', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'aa5e8cfc-b891-4aff-aa66-7268fc960b6f', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "AI outputs shall be evaluated against predefined acceptance criteria before release.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Output Evaluation", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_LIMITED", "AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "cb042c1e-74f0-4813-950d-11306f813b13", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Evaluation Report, UAT Results, Test Evidence", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Have AI outputs been evaluated before deployment? Have acceptance criteria been defined and approved? Has testing been performed using representative business scenarios? Have evaluation results been documented and reviewed? Are identified issues tracked and resolved before release?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('8f0ee3a8-ba35-489a-90f8-8614af5bcaf3', 'CREATED', 'CONTROL_DEFINITION', '30f82d10-42ce-4e2c-9450-702c4f6c5f1b', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "DEL-18", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('bcb5ac36-e930-45ec-a290-a010d10f294b', 'CREATED', 'CONTROL_DEFINITION_VERSION', '9df47e51-5b3c-402e-a349-cd39d5049509', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "Human oversight mechanisms shall be documented and implemented when required by the AI risk classification.", "ownerTeam": "DIGITAL_DATA", "statement": "AI Human Oversight Design", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "30f82d10-42ce-4e2c-9450-702c4f6c5f1b", "reviewerTeam": "AI", "sourceOfTruth": "https://sanofi.sharepoint.com/sites/ORAIGovernance/SitePages/OR.AI-Opella%20Responsible%20AI.aspx", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Design Documentation, User Procedures", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Are human oversight mechanisms defined and documented? Can users intervene, challenge, approve, or override AI outputs when required? Are roles and responsibilities for oversight clearly defined? Is evidence of human approval or review retained where applicable?", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('77dc7286-adcf-420d-875e-0d4e37a27de3', 'CREATED', 'CONTROL_DEFINITION', 'f7eb8763-84da-44a6-b65a-a09c1148458b', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "QUAL-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('b07e0d65-d3a4-4ea0-bc15-e9e8f0942916', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'c479909e-d720-42a4-8e3c-ccc33f10a5fd', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SUPPLIER", "objective": "According to a risk based approach based on the third party risk identification process,  the Digital Opella contract Owner (the person requesting and managing the contract process) must ensure that Quality contractual Clauses, Cyber Security measures, and Data Privacy Agreements relevant to the scope of services* are included in a contract with the third party.   \n\n*Note : a Contract, including Master Service Agreement can cover services related to one or several digital solutions.", "ownerTeam": "CYBER_SECURITY", "statement": "Contract", "triggerRule": {"groups": [{"conditions": [{"values": ["THIRD_PARTY_ENGAGED"], "operator": "IN", "outcomeKey": "THIRD_PARTY_ENGAGEMENT"}]}]}, "definitionId": "c0d8903d-61e2-42f7-828c-fe183fd0b0a4", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DFC-QU-GOP-0000498-CS Third Party Quality Management - Sourcing, Contracting, Management and Termination: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/724974 \n2. For Cyber: DIG-CO-STD-0000020-Third Parties - Contractors Cybersecurity requirements: https://opella-connect.veevavault.com/ui/#permalink=V190000000IY025", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Reference of established contract, agreement or Purchase order including proper clauses for each 3rd party used.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\nFor each Third Party providing or supporting the digital solution (SaaS system, On-Premise Software, Middleware, Infrastructure or Platform provider, Managed Services, Outsourced services):\n\n- For Third Party identified as a “High Risk third party”* the control is to be attested in alignement with compliance status found into the High-Risk Third-Party dashboard.\n \nOtherwise:\n \nFor Third Party supporting a GxP  feature / process: \n- Are quality contractual clauses signed by authorized Opella and third party signatories, included into the contract and stored in a contract management system? If not, has a quality contractual clause exemption form been approved by the Contract owner?  \n\n- If the contract is up for renewal by end of the current year, and the contractual clauses have been signed for more than 5 years, is a gap assessment documented and an action plan defined for remediations?\n \nFor Third-Party that either accesses, stores or manages Opella information, has access to Opella systems, or has privileged access, or supports a vital process: Are the Cyber contractual measures included into the contract?\n \nFor Third-Party processing personal data: Is the Data Privacy Agreement included into the contract?\n \n* A High Risk Third Party is a provider supporting either a Vital activity or handling high risk data (highly sensitive data, sensitive personal data or GxP  / SOX relevant data).", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('a580ae36-e754-4241-bfd0-0aacedf452a5', 'CREATED', 'CONTROL_DEFINITION', '344d3144-e168-4082-81cf-2a2ea91ca041', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SUP-03_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('81207863-5115-4a57-9fa6-bb3d2f594424', 'CREATED', 'CONTROL_DEFINITION_VERSION', '60c1ef00-4651-4ecc-8215-bf2cb967ffba', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SUPPLIER", "objective": "According to a risk based approach based on the third party risk identification process, an assessment of the 3rd Party is performed in order to evaluate quality, cyber and data privacy compliance. The results of this assessment are documented; it confirms the 3rd party meets Opella requirements to begin providing the solution or service.   \n\nFor SOX digital solutions and associated infrastructure components under the scope of the SOX annual campaign: A yearly independent assessment must be provided for any service outsourced to a Third Party so that compliance assurance is obtained.", "ownerTeam": "CYBER_SECURITY", "statement": "3rd Party Assessments", "triggerRule": {"groups": [{"conditions": [{"values": ["THIRD_PARTY_ENGAGED"], "operator": "IN", "outcomeKey": "THIRD_PARTY_ENGAGEMENT"}]}]}, "definitionId": "344d3144-e168-4082-81cf-2a2ea91ca041", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DFC-QU-GOP-0000498-CS Third Party Quality Management - Sourcing, Contracting, Management and Termination: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/724974\n2. DFC-QU-GOP-0000204-Computerized Systems Third-Party Assessments: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/351770 \n3. For Cyber: DIG-CO-STD-0000020-Third Parties - Contractors Cybersecurity requirements: https://opella-connect.veevavault.com/ui/#permalink=V190000000IY025", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Third party Assessments performed including: third party audit/assessment report, Cyber Security certificates evaluation or completed VIRP, Data Privacy assessment.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\nFor each Third Party providing or supporting the digital solution (SaaS system, On-Premise Software, Middleware, Infrastructure or Platform provider, Managed Services, Outsourced services):\n \nFor Third Party identified as a “High Risk third party”*, the control is to be attested in alignement with compliance status found into the High-Risk Third-Party dashboard.\n \nOtherwise, \n \n- For Quality Assessment:\nBased on the Third Party Risk Identification form result for the Third Party, if a Quality Assessment or Quality audit was required, has it been executed and recorded into CONNECT?\n\n- For VIRP (Cyber-Security) Assessment:\nIf the Third-Party either accesses, stores or manage Opella information, has access to Opella systems, or has privileged access, or supports a vital process: Has a VIRP assessment been completed and registered in the CyberVadis tool?\n \n- For Data Privacy Assessment :\nIf the Third Party processes personal data: Has a Data Privacy assessment been performed in OneTrust?\n \n* A High Risk Third Party is a provider supporting either supporting a Vital activity or handling high risk data (highly sensitive data, sensitive personal data or GxP  / SOX relevant data).", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('50325165-5889-4b1b-9656-f88887d02674', 'CREATED', 'NFR_DEFINITION_VERSION', 'ad268533-1e06-4467-b6f0-14da12d4010e', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "Prefer solution is Opella SSO / AzureAD / Akamai.\n\nIf it''s a PAM or Opella account, then Identity shall be used:\n     --> https://identity.sanofi.com/edentity/ui/setTimeZone.jsf\n\nNote: If you are specifically using a PAM service account, even though they have no password expiration, they are still bounded by a regular change of password to ensure there is no unauthorized access.\n\n1. The digital solution must have the capability to change a password. \n2. The digital solution must enable this capability when a password is forgotten.\n3. The existing password must be entered prior to initiating a new password change.\n4. If a new password is successfully accepted per the Password Creation rules, digital solution must send an email to the owner of the user ID to inform the owner of the password change.\n5. When a user forgets a password, the password is changed and not recovered, avoiding password not to be stored encrypted, as requested by the Cryptography Policy DFC-QU-STD-0000259-Cryptography Standard: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/500892.", "ownerTeam": "CYBER_SECURITY", "statement": "I want to ensure password changes are completed securely.", "triggerRule": {"groups": [{"conditions": [{"values": ["ACCESS_RESTRICTED"], "operator": "IN", "outcomeKey": "ACCESS"}]}]}, "definitionId": "8f4e7c9f-6a65-499a-b0b1-829355063268", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": false, "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('d9b503ed-eae7-472d-afec-7630c428bdee', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'ca7359d5-e96a-47a7-8d7f-20ecb6e21d08', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_QUALITY", "objective": "Records generated throughout the digital solution lifecycle (e.g Specifications, Access Request records etc) must be maintained and retained as per the Opella Record Retention Schedule that defines the retention period.", "ownerTeam": "DIGITAL_QUALITY", "statement": "Records Retention", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "f7eb8763-84da-44a6-b65a-a09c1148458b", "reviewerTeam": "QUALITY", "sourceOfTruth": "DFC-QU-GOP-0000296-Project & System Lifecycle: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/484176", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "*Inventory/list of records generated throughout the digital solution lifecycle (e.g Specifications, Access Request records, test evidence, CRs, etc)\n*Record retention log or archive index mapping each record type to its defined retention period per the Opella Record Retention Schedule\n*Evidence records are stored in a manner that ensures they remain accessible and legible for their full retention period\n* Disposal/destruction record for any documents reaching end of retention, showing this was executed per the schedule (not ad hoc)", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n* Have all record types generated throughout the digital solution lifecycle been identified and mapped to the Opella Record Retention Schedule?\n* Are records actually being retained for the period defined in the schedule (not shorter and not definitely without justification)?\n* Are records stored in a format/location that keeps them accessible and legible throughout the retention period?\n* Where retention periods have lapsed, was disposal handled per the defined process (not informal deletion)?\n* Any record type missing a defined retention period, or retained/disposed of outside the schedule, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('fbd84489-94d1-4289-9d84-a2d2406568f0', 'CREATED', 'CONTROL_DEFINITION', 'c15f26b3-bb8d-49f0-aac3-15f60135ec76', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "QUAL-02", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('e3d38cc7-212f-4ac1-a142-f9f00d6e0fe1', 'CREATED', 'CONTROL_DEFINITION_VERSION', '9e9e0135-3608-4838-9fe5-d0331c53ddbf', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_QUALITY", "objective": "Detected or potential GxP-related compliance failures impacting a digital solution must be reported as a Quality Event. Each event must be assessed with respect to GxP/Regulatory compliance, Product impact, and Safety, Patients, Data reliability. The associated action plans supporting resolution must be tracked as Corrective Actions and/or Preventive Actions (CAPAs).\n \nNote: For Quality Events reported as non-significant deviations, a Corrective Action and/or Preventive Action is not required.", "ownerTeam": "DIGITAL_QUALITY", "statement": "Deviation", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "c15f26b3-bb8d-49f0-aac3-15f60135ec76", "reviewerTeam": "QUALITY", "sourceOfTruth": "1. GQCMS-QU-GOP-0000518-Management of Deviations in QualiPSO: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/741670\n2. GQCMS-QU-GOP-0000286-Escalation of Quality Events and Management of Quality Alerts: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/470603\n3. GQCMS-QU-GOP-0000595-Corrective Action, Preventive Action and Effectiveness Check Management: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/856185", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "* Quality Event record documenting the detected or potential GxP-related compliance failure\n* Assessment documentation covering GxP/Regulatory compliance impact, Product impact, and Safety/Patients/Data reliability impact\n* For significant deviations: CAPA record(s) tracking the associated action plan through to resolution\n*For on-significant deviations: documented rationale confirming CAPA was correctly determined not required\n* Escalation record, where the Quality Event required escalation per the Management of Quality Alerts process", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n* Was the GxP-related compliance failure reported as a Quality Event in a timely manner?\n* Was the event assessed against all required dimensions - GxP/Regulatory compliance, Product impact, and Safety/Patients/Data reliability?\n* For deviations assessed as significant: was a CAPA created and tracked to resolution?\n* For deviations assessed as non-significant: is the \"CAPA not required\" determination documented and justified, not just assumed?\n* Was escalation triggered where the eent met escalation criteria?\n* Any GxP-related compliance failure not reported as a Quality Event, or missing a documented significance assessment, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('95d564d0-dd3d-436d-94e2-87431741956f', 'CREATED', 'CONTROL_DEFINITION', 'ddefb2b3-1764-4143-bb64-795b91d1917d', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "QUAL-03", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('a6e1ea8b-ecee-4e1f-b8e7-5476aebf51d2', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'c0efc3fe-6376-4ccf-8e0b-ba83f6d43db2', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "RUN", "itProcess": "MANAGE_QUALITY", "objective": "The remediation of detected or potential failures of a digital  solution to comply with applicable regulatory (e.g. GxP, SOX, CSRD) or Opella requirements  must be tracked and monitored until completion to ensure timely and committed resolution.", "ownerTeam": "DIGITAL_QUALITY", "statement": "Corrective Action Preventive Action", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "ddefb2b3-1764-4143-bb64-795b91d1917d", "reviewerTeam": "QUALITY", "sourceOfTruth": "QUA-CO-SOP-0010049-Management of CAPA and Effectiveness:", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "* CAPA record(s) tracking remediation of detected/potential failures against applicable regulatory requirements (GxP, SOX, CSRD) or Opella requirements\n* Action plan with defined owner, due date, and remediation steps\n* Status tracking evidence showing CAPA progress until completion (not just opened and left open)\n* Effectiveness check record confirming the corrective/prevventive action actually resolved the underlying issue\n* Escalation or overdue - CAPA report, where applicable, showing timely resolution was monitored", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n* Is every CAPA arising from a detected or potential failure tracked with an assigned owner and due date?\n* Is CAPA status monitored and updated until formal completion/closure?\n* Was an effectiveness check performed to confirm the corrective/preventive action resolved the root cause (not just closed administratively)?\n* Are overdue CAPAs identified and escalated per the defined process?\n* Any CAPA left open past its due date without escalation, or closed without an effectiveness check, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": 12}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('3ad10cbd-b834-47fa-8afb-fa739d9ae2d2', 'CREATED', 'CONTROL_DEFINITION', '9fb42a0c-fc9c-496a-9e5f-89f3d4fce9bf', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "RISK-03", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('01f67c52-0c69-46d9-a20f-0d27dcd15b4c', 'CREATED', 'CONTROL_DEFINITION_VERSION', '4ad98c5b-3596-42be-b557-23fd45ff877e', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Infrastructure vulnerability exposure of the digital solution must be monitored all along its lifecycle to ensure it is exempt from known vulnerabilities.", "ownerTeam": "CYBER_SECURITY", "statement": "Vulnerability Lifecycle Program", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}]}]}, "definitionId": "ff75b318-1ea7-4e3a-a6e6-aad5947da36f", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-STD-0000031-Systems Security Standard: https://opella-connect.veevavault.com/ui/#permalink=V190000000IV019", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "If a vulnerability is identified through a Qualys scan, the corresponding report will be shared with the application owner, who is responsible for taking the necessary remediation actions within the required timelines.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "If a vulnerability is identified through a Qualys scan, the corresponding report will be shared with the application owner, who is responsible for taking the necessary remediation actions within the required timelines.", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('bdf75e73-1cc0-4bcc-92ce-26292f214cd8', 'CREATED', 'CONTROL_DEFINITION_VERSION', '39b7ebb7-bb40-4a34-9c89-b308a3a0568e', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_RISK", "objective": "The digital solution''s functions or components must be assessed for potential risks to business, patient safety, product quality, data integrity, and regulatory compliance in the event of a failure. The assessment determines the depth of expected tests or verifications to ensure these risks are controlled.", "ownerTeam": "CYBER_SECURITY", "statement": "Assess Functional Risk", "triggerRule": {"groups": [{"conditions": [{"values": ["GXP"], "operator": "IN", "outcomeKey": "GXP_CLASSIFICATION"}]}]}, "definitionId": "9fb42a0c-fc9c-496a-9e5f-89f3d4fce9bf", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "1. DIG-CO-SOP-0018146-System Life Cycle: https://opella-connect.veevavault.com/ui/#permalink=V190000000IO009", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "The risk assessment of the digital solution''s functionalities or components, describing the impact in case of failure and level of testing or verification required.\nE.g.: Risk issue in JIRA, Risk record in HP ALM, Functional Risk Assessment in Connect CMS...).", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following: \n\n* Has a risk assessment been performed for the digital solution''s functionalities or components, describing the impact in case of failure?\n* Does the assessment determine the appropriate level of testing or verification required based on the identified risk?\n* Is the risk assessment recorded in the appropriate tool for the solution (eg. Risk issue in Jira, Risk record in HP ALM, Functional Risk Assessment in Connect CMS)?\n* Does the assessment cover all functionalities/components in scope, with no material gaps?\n* Is there evidence the resulting testing/verification level was actually applied downstream (eg. traceable to the test strategy)?\n* Any functionality or component without a documented functional risk assessment, or where the assigned testing rigor doesn''t match the assessed risk, should be treated as non-compliant.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('8e653f19-a155-4712-ad5c-9bbc804a8b39', 'CREATED', 'CONTROL_DEFINITION', '1a730c5b-cb00-4b6d-90bd-aecfcb374f10', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SEC-01", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('27d0061a-7fe7-4d73-b5e8-a52fd348939e', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'b95e5e7f-5f85-4200-9ec6-7aacbc4ab590', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Threats must be identified so that risky scenarios can be understood and mitigated.", "ownerTeam": "CYBER_SECURITY", "statement": "Threat Modeling", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["OPELLA_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}]}, "definitionId": "1a730c5b-cb00-4b6d-90bd-aecfcb374f10", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "QU-STD-0000469 Secure Development of Applications: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/910529", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Cybersecurity Threat assessment describing the cyber security risks which can impact the digital solution and the mitigition plan.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Create a Security Architecture Review Intake using the form : https://opella-health.atlassian.net/wiki/spaces/CYBSECKB10/pages/557974353/Security+Architecture+Review+Intake", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('2fd48562-17f9-4349-b6d0-8e23a157381d', 'CREATED', 'CONTROL_DEFINITION', '8c32ecff-c911-4b5e-8fa5-0821d361fcab', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SEC-02_SIC", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('6b85a722-74b7-4ad6-be65-70f520121de4', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'c99f0245-e7d8-470b-8f49-20820aae9fab', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Vulnerabilities at code level of the digital solution must be identified and remediated. Additionally, if open source dependencies within the code are used then they must be reviewed to ensure proper use.", "ownerTeam": "CYBER_SECURITY", "statement": "Cyber Security Code Scan", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}, {"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["LIKE_EXTERNAL"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}, {"conditions": [{"values": ["WEBSITE"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["FULLY_MANAGED"], "operator": "IN", "outcomeKey": "PLATFORM_TYPE"}]}]}, "definitionId": "8c32ecff-c911-4b5e-8fa5-0821d361fcab", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "QU-STD-0000469 Secure Development of Applications:  https://api-eu.sanofi.com:8443/smartlink/api/qualipso/910529", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Result of the code scan with list of vulnerabilities detected and indicating that no critical/high vulnerabilities remains open.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "When attesting this control, consider the following:\n\n - Is the code of the digital solution stored into Opella GitHub repository?\n - Has a Cybersecurity code scan been requested and completed, before the release into production, to detect potential vulnerabilities?\n - Is a proof available, including at least: the list of vulnerabilities detected, the scan identifier, the date of the scan, the branch that was scanned, the result of the scan (SCA, SAST...) and name of the person who realized the screenshot and the timestamp?\n - If Critical/High vulnerabilities have been identified, have they been remediated before deployment in Production?\n\nIf open-source code is used:\n - Have we ensured compliance usage with the license terms (e.g. use for commercial purposes allowed, number of workstations allowed)?", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('6c75e78a-728b-40db-a0da-943b9468b9f5', 'CREATED', 'CONTROL_DEFINITION', 'd432e481-f311-4de4-9c70-5e0447cb7478', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SEC-03", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER');
INSERT INTO public.audit_event VALUES
	('3641fce1-2cdb-4f90-a299-9b278611d020', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'ccdbc1cb-af46-4d6d-abf8-534f09a90d38', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Vulnerabilities of cloud environment of the digital solution must be identified and remediated.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Cloud Security Posture", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}]}, "definitionId": "d432e481-f311-4de4-9c70-5e0447cb7478", "reviewerTeam": "INFRASTRUCTURE", "sourceOfTruth": "DIG-CO-STD-0000031-Systems Security Standard:https://opella-connect.veevavault.com/ui/#permalink=V190000000IV019", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "PRISMA/ SonarCube cloud service monitoring report indicating that no medium or high vulnerabilities are open.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "PRISMA/ SonarCube cloud service monitoring report indicating that no medium or high vulnerabilities are open.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('7a83983a-39aa-4333-b298-b8b49c71dbc9', 'CREATED', 'CONTROL_DEFINITION', 'ff75b318-1ea7-4e3a-a6e6-aad5947da36f', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SEC-04", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('6bcc3588-4843-424d-8e9f-22a3bbc0b82b', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'a0d5e34f-19b4-4f59-96cc-54a6e17322af', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Attacks must be simulated to identify overall vulnerabilities before releasing the digital solution to production .", "ownerTeam": "CYBER_SECURITY", "statement": "Cyber Pentest", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["HIGHLY_CONFIDENTIAL"], "operator": "IN", "outcomeKey": "CONFIDENTIALITY_CLASSIFICATION"}]}]}, "definitionId": "f2f41516-384f-4243-8cee-2665f6bf3f38", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "DIG-CO-STD-0000031-Systems Security Standard: https://opella-connect.veevavault.com/ui/#permalink=V190000000IV019", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Cyber pentest report summarizing the simulation of the attacks on the digital solution executed and critial risks remediated.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Cyber pentest report summarizing the simulation of the attacks on the digital solution executed and critial risks remediated.", "autoAttestationRule": {"outcomeKey": "PLATFORM_TYPE", "acceptedValues": ["FULLY_MANAGED"]}, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('73cfcdab-c3f6-4000-9a9b-b35c2e16140f', 'CREATED', 'CONTROL_DEFINITION', 'de43c30e-4a93-430b-a208-bb95f4d56a09', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SEC-06", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('f96d6296-ac15-4cfe-a2ea-8a72866d3079', 'CREATED', 'CONTROL_DEFINITION_VERSION', 'b1ceafd7-f1c2-4ea9-93ff-9e40956535ce', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "If the digital solution is used in China:\nIt must comply with laws and regulations under China''s cyber security and data security regime.\n\nFor digital solutions hosted outside Mainland China: If No personal information or only Technical Personal data is collected from Mainland China, this control is not applicable. Otherwise a China Cross-Border Data Transfer – Personal Information (CBDT-PI) risk review must be included.\n\nFor digital solutions hosted in Mainland China: this control must be addressed.", "ownerTeam": "CYBER_SECURITY", "statement": "China Digital Compliance Requirement", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["USED_IN_CHINA"], "operator": "IN", "outcomeKey": "TERRITORIAL_COMPLIANCE_EXTENSION"}]}]}, "definitionId": "de43c30e-4a93-430b-a208-bb95f4d56a09", "reviewerTeam": "CYBERSECURITY", "sourceOfTruth": "QU-GOP-0001332 China Digital Compliance Framework: https://api-eu.sanofi.com:8443/smartlink/api/qualipso/8565258", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "Requestor to contact GRC team - CyberGRC@Opella.com for further instructions", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "Requestor to contact GRC team - CyberGRC@Opella.com for further instructions", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('801b7cfb-3f1c-4f08-bd57-204a4c11b9ae', 'CREATED', 'CONTROL_DEFINITION', '92a8f9f1-754b-46b1-bb4d-9d9b0f956b4d', 'seed-user-admin-clara', NULL, NULL, '{"after": {"code": "SEC-07", "active": true, "createdByUserId": "seed-user-admin-clara"}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
	('e3494806-2e76-4c56-abb7-50f587425738', 'CREATED', 'CONTROL_DEFINITION_VERSION', '641163d0-dea1-4ee2-bb88-2bee774c71cd', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_SECURITY", "objective": "Vulnerabilities of cloud infrastructure code of the digital solution must be identified and remediated.", "ownerTeam": "DIGITAL_TECHNOLOGY", "statement": "Cloud infrastructure code scan", "triggerRule": {"groups": [{"conditions": [{"values": ["WEBSITE", "MOBILE_APP", "CHATBOT"], "operator": "IN", "outcomeKey": "PROPERTY_TYPE"}, {"values": ["EXTERNALLY_MANAGED_PLATFORM"], "operator": "IN", "outcomeKey": "PLATFORM_HOSTING"}]}]}, "definitionId": "92a8f9f1-754b-46b1-bb4d-9d9b0f956b4d", "reviewerTeam": "INFRASTRUCTURE", "sourceOfTruth": "DIG-CO-STD-0000031-Systems Security Standard: https://opella-connect.veevavault.com/ui/#permalink=V190000000IV019", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "APPROVAL_REQUIRED", "createdByUserId": "seed-user-admin-clara", "evidenceRequired": true, "targetedEvidence": "PRISMA/ SonarCube code scan report from Github repository indicating that no medium or high vulnerabilities are open.", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "PRISMA/ SonarCube code scan report from Github repository indicating that no medium or high vulnerabilities are open.", "autoAttestationRule": null, "assessmentTemplateKey": null, "revalidationIntervalMonths": null}, "before": null}', '2026-09-09 08:28:45.407', 'USER'),
